  "typescriptCustomType" : "class Sea {
    __ans: number[][];
    __guesses: number;
    constructor(ans: number[][]) {
        this.__ans = ans;
        this.__guesses = 400;
    }

    hasShips(topRight: number[], bottomLeft: number[]): boolean {
        this.__guesses -= 1;
        var ret = false;
        for (let a of this.__ans) {
            var cur = a[0] >= bottomLeft[0] && a[0] <= topRight[0] && a[1] >= bottomLeft[1] && a[1] <= topRight[1];
            ret = ret || cur;
        }
        return ret;
    }

    getGuesses(): number {
        return this.__guesses;
    }
};
